float hash11(float p){
uint x=floatBitsToUint(p);
x=((x>>16u)^x)*2146503469u;
x=((x>>16u)^x)*2146503469u;
x=(x>>16u)^x;
return float(x>>8u)*(1./16777216.);
}
float hash21(vec2 p){
uint h=floatBitsToUint(p.x)*2146503469u^floatBitsToUint(p.y)*1804288421u;
h=((h>>16u)^h)*1103515245u;
h=(h>>15u)^h;
return float(h>>8u)*(1./16777216.);
}
int qOctaves(int maxOct){
return int(float(maxOct)*mix(.5,1.,uQuality)+.5);
}
vec3 retroQuantize(vec3 col,const vec3 pal[16],int n,vec2 px){
float d=bayer4(px)-.5;
vec3 c=col+d*(1./float(n));
int best=0;
float bd=1e9;
for(int i=0;i<16;i++){
if(i>=n)break;
vec3 diff=c-pal[i];
float dd=dot(diff,diff);
if(dd<bd){bd=dd;best=i;}
}
return pal[best];
}
float scanline(vec2 fragCoord,float strength){
return 1.-strength*(.5+.5*sin(fragCoord.y*3.14159265));
}
float vnoise(vec2 p){
vec2 i=floor(p);
vec2 f=fract(p);
vec2 u=f*f*(3.-2.*f);
float a=hash21(i);
float b=hash21(i+vec2(1.,0.));
float c=hash21(i+vec2(0.,1.));
float d=hash21(i+vec2(1.,1.));
return mix(mix(a,b,u.x),mix(c,d,u.x),u.y)*2.-1.;
}
float wrapTime(float t,float period){
return t-period*floor(t/period);
}
float drawGlyph(vec2 fragPx,vec2 origin,float scale,int code){
vec2 rel=(fragPx-origin)/scale;
if(rel.x<0.||rel.y<0.||rel.x>=8.||rel.y>=8.)return 0.;
uvec2 g=fontGlyph(code);
int col=int(rel.x);
int row=7-int(rel.y);
uint bits=(row<4)?(g.x>>(8u*uint(3-row))):(g.y>>(8u*uint(7-row)));
return float((bits>>(7u-uint(col)))&1u);
}
float fbmPx(vec2 p,float px){
float amp=.5;
float sum=0.;
float f=1.;
int oct=qOctaves(16);
for(int i=0;i<16;i++){
if(i>=oct)break;
float w=detailFade(1./(f*px));
if(w<=0.)break;
sum+=amp*w*vnoise(p);
p=p*2.03+vec2(11.7,5.1);
f*=2.03;
amp*=.5;
}
return sum;
}
vec3 retroFinalize(vec3 col,vec2 uv,vec2 fragCoord,const vec3 pal[16],int n){
vec3 q=retroQuantize(clamp(col,0.,1.),pal,n,fragCoord);
float d=distance(uv,vec2(.5));
return q*(1.-.25*smoothstep(.45,.9,d));
}
const float DC_TAU=6.28318530718;
const float DC_CELL=1./6.;
const float DC_LINE=.0075;
const float DC_R=.84;
const float DC_LINES=288.;
const float DC_TRIADS=640.;
const float DC_SCENE=21.3333333;
const float DC_CLOCK0=86400.-2.*DC_SCENE+2.2;
const vec3 DC_GRAY=vec3(.42,.42,.4);
const vec3 DC_WHITE=vec3(.92,.91,.86);
const vec3 DC_BLACK=vec3(.04,.04,.05);
const vec3 DC_NIGHT=vec3(.07,.04,.14);
const vec3 DC_MAGENTA=vec3(1.,.18,.7);
const vec3 DC_CYAN=vec3(.12,.92,1.);
const vec3 DC_VIOLET=vec3(.48,.24,.95);
const vec3 DC_AMBER=vec3(1.,.66,.2);
const vec3 DC_BARS[8]=vec3[8](
vec3(.75),vec3(.75,.75,0.),vec3(0.,.75,.75),vec3(0.,.75,0.),
vec3(.75,0.,.75),vec3(.75,0.,0.),vec3(0.,0.,.75),DC_BLACK
);
const vec3 DC_NEON[8]=vec3[8](
DC_WHITE,DC_AMBER,DC_CYAN,vec3(.2,.55,1.),
DC_MAGENTA,DC_VIOLET,vec3(.3,.08,.45),DC_BLACK
);
const float DC_BURST[6]=float[6](6.,10.,16.,26.,40.,64.);
const vec3 PALETTE[16]=vec3[16](
DC_BLACK,DC_GRAY,DC_WHITE,
vec3(.75),vec3(.75,.75,0.),vec3(0.,.75,.75),vec3(0.,.75,0.),
vec3(.75,0.,.75),vec3(.75,0.,0.),vec3(0.,0.,.75),
DC_MAGENTA,DC_CYAN,DC_VIOLET,DC_AMBER,DC_NIGHT,vec3(1.)
);
const int PALETTE_N=16;
float dcFill(float d,float px){
return clamp(.5-d/px,0.,1.);
}
float dcBox(vec2 p,vec2 c,vec2 hs){
vec2 d=abs(p-c)-hs;
return length(max(d,0.))+min(max(d.x,d.y),0.);
}
const vec4 DC_NOGLYPH=vec4(0.,0.,1.,-1.);
vec4 dcText(vec2 p,vec2 c,float gh,int n,int s[16]){
float sc=gh/8.;
vec2 o=c-vec2(float(n)*gh*.5,gh*.5);
vec2 rel=(p-o)/sc;
if(rel.x<0.||rel.y<0.||rel.y>=8.)return DC_NOGLYPH;
int i=int(rel.x/8.);
if(i>=n)return DC_NOGLYPH;
return vec4(o+vec2(float(i)*gh,0.),sc,float(s[i]));
}
float dcGlyph(vec2 p,vec4 g){
return g.w<0.?0.:drawGlyph(p,g.xy,g.z,int(g.w));
}
vec4 dcId(vec2 p,vec2 c,float gh,int sel){
int s[16]=int[16](68,69,77,79,71,69,78,32,84,86,32,32,32,32,32,32);
int n=10;
if(sel==1){s=int[16](73,78,84,82,85,83,73,79,78,32,32,32,32,32,32,32);n=9;}
if(sel==2){s=int[16](78,79,32,83,73,71,78,65,76,32,32,32,32,32,32,32);n=9;}
if(sel==3){s=int[16](72,65,67,75,69,68,32,32,32,32,32,32,32,32,32,32);n=6;}
return dcText(p,c,gh,n,s);
}
vec4 dcClock(vec2 p,vec2 c,float gh,float t){
float s=wrapTime(floor(max(t,0.)),86400.);
int h=int(s/3600.);
int m=int(mod(s,3600.)/60.);
int x=int(mod(s,60.));
int str[16]=int[16](48+h/10,48+h%10,58,48+m/10,48+m%10,58,
48+x/10,48+x%10,32,32,32,32,32,32,32,32);
if(t<0.)str=int[16](45,45,58,45,45,58,45,45,32,32,32,32,32,32,32,32);
return dcText(p,c,gh,8,str);
}
vec4 dcHex(vec2 p,vec2 o,float gh,int n,float seed){
float sc=gh/8.;
vec2 rel=(p-o)/sc;
if(rel.x<0.||rel.y<0.||rel.y>=8.)return DC_NOGLYPH;
int i=int(rel.x/8.);
if(i>=n||i%3==2)return DC_NOGLYPH;
int d=int(hash21(vec2(float(i),seed))*16.);
return vec4(o+vec2(float(i)*gh,0.),sc,float(d<10?48+d:55+d));
}
float dcZonePlate(vec2 d,float rad,float px){
const float K=350.;
float r=length(d)/rad;
float cyc=K*r/(3.14159265*rad);
return .5+.5*cos(K*r*r)*detailFade(1./max(cyc*px,1e-6));
}
vec3 dcCard(vec2 p,float ax,float px,float clock,int idSel,float neon,out vec4 glyph,out vec3 glyphInk){
glyph=DC_NOGLYPH;
glyphInk=vec3(1.);
vec3 ink=mix(DC_WHITE,DC_CYAN,neon);
vec3 col=mix(DC_GRAY,DC_NIGHT*1.6,neon);
vec2 g=abs(fract(p/DC_CELL+.5)-.5)*DC_CELL;
col=mix(col,ink,max(dcFill(g.x-DC_LINE*.5,px),dcFill(g.y-DC_LINE*.5,px)));
if(ax-abs(p.x)<DC_CELL*.5||1.-abs(p.y)<DC_CELL*.5){
vec2 cell=floor(p/DC_CELL);
col=mix(DC_BLACK,ink,mod(cell.x+cell.y,2.));
}
const float ZR=.26;
vec2 zd=abs(p)-vec2(ax-.46,.6);
float zl=length(zd);
if(zl<ZR+DC_LINE){
vec3 zp=vec3(dcZonePlate(zd,ZR,px))*mix(vec3(1.),DC_MAGENTA,neon*.7);
col=mix(col,zp,dcFill(zl-ZR,px));
col=mix(col,ink,dcFill(abs(zl-ZR)-DC_LINE*.5,px));
}
float r=length(p);
if(r<DC_R+DC_LINE){
vec3 c=col;
float x=p.x;
float y=p.y;
float u=clamp((x+DC_R)/(2.*DC_R),0.,.9999);
if(y>.5&&y<.6667){
float box=dcFill(dcBox(p,vec2(0.,.5833),vec2(.46,.0833-DC_LINE*.5)),px);
c=mix(c,DC_BLACK,box);
glyph=dcId(p,vec2(0.,.5833),.09,idSel);
glyphInk=ink;
}else if(y>.25&&y<=.5){
int i=int(u*8.);
c=mix(DC_BARS[i],DC_NEON[i],neon);
}else if(y>.0833&&y<=.25){
c=vec3(mix(.05,.92,floor(u*6.)/5.));
c=mix(c,c*DC_VIOLET*1.6,neon*.6);
}else if(y>-.0833&&y<=.0833){
c=DC_BLACK;
c=mix(c,ink,dcFill(abs(y)-DC_LINE*.5,px));
c=mix(c,ink,dcFill(abs(x)-DC_LINE*.5,px)*step(abs(y),.06));
}else if(y>-.3333&&y<=-.0833){
int i=int(u*6.);
float f=DC_BURST[i];
float v=.5+.5*cos(DC_TAU*f*x)*detailFade(1./(f*px));
c=mix(DC_BLACK,mix(DC_WHITE,DC_CYAN,neon),v);
}else if(y>-.5&&y<=-.3333){
c=mix(DC_BLACK,mix(DC_WHITE,DC_MAGENTA,neon),u);
}else if(y>-.6667&&y<=-.5){
float box=dcFill(dcBox(p,vec2(0.,-.5833),vec2(.4,.0833-DC_LINE*.5)),px);
c=mix(c,DC_BLACK,box);
glyph=dcClock(p,vec2(0.,-.5833),.09,clock);
glyphInk=mix(DC_WHITE,DC_AMBER,neon);
}
col=mix(col,c,dcFill(r-DC_R,px));
col=mix(col,ink,dcFill(abs(r-DC_R)-DC_LINE*.5,px));
}
return col;
}
vec2 dcScreen(vec2 uv,float px,out float inside){
vec2 c=uv*2.-1.;
c*=1.+vec2(.03,.045)*(c.yx*c.yx);
vec2 d=abs(c)-vec2(.93);
inside=dcFill(length(max(d,0.))+min(max(d.x,d.y),0.)-.07,px);
return c*.5+.5;
}
float dcStripe(float ph,float c){
return .3+.7*(1.-smoothstep(.09,.2,abs(fract(ph-c+.5)-.5)));
}
vec3 dcTube(vec3 col,vec2 q,float inside){
float s=.5+.5*cos(DC_TAU*q.y*DC_LINES);
float lum=dot(col,vec3(.2126,.7152,.0722));
float scan=mix(.72+.56*s,1.,lum*.4);
col*=mix(1.,scan,detailFade(iResolution.y/DC_LINES));
float ph=fract(q.x*DC_TRIADS);
vec3 m=vec3(dcStripe(ph,1./6.),dcStripe(ph,.5),dcStripe(ph,5./6.))/.56;
col*=mix(vec3(1.),m,.85*detailFade(iResolution.x/DC_TRIADS*.5));
vec2 cq=q*2.-1.;
col*=mix(1.08,.7,smoothstep(.3,1.7,dot(cq,cq)));
vec2 out2=max(abs(cq)-1.,0.);
vec3 bezel=vec3(.05,.048,.056)+vec3(.05,.06,.07)*exp(-length(out2)*18.);
return mix(bezel,col,inside);
}
float dcTear(float y,float t,float amt){
float band=floor(y*36.);
float fast=floor(t*12.);
float slow=floor(t*1.5);
float jitter=(hash21(vec2(band,fast))-.5)*.04*step(.6,hash21(vec2(band+3.,fast)));
float h=hash21(vec2(band,slow+101.));
float jump=step(1.-.2*amt,h)*(hash21(vec2(band+7.,slow))-.5)*.3;
float wave=sin(y*9.+t*2.3)*.012+sin(y*31.-t*5.1)*.005;
return amt*(jitter+jump+wave);
}
vec2 dcBlocks(vec2 q,float t,float amt){
vec2 cell=floor(q*vec2(24.,14.));
float tick=floor(t*1.5);
float h=hash21(cell+vec2(tick*7.,tick*3.));
if(h>.22*amt)return vec2(0.);
vec2 r=vec2(hash21(cell+vec2(tick,19.)),hash21(cell+vec2(31.,tick)))-.5;
return r*vec2(.35,.12);
}
float dcSnow(vec2 q,float t){
vec2 cells=max(vec2(DC_TRIADS*.75,DC_LINES),floor(iResolution.xy/3.));
vec2 cell=floor(q*cells);
float fr=floor(t*30.);
float grainPx=min(iResolution.x/cells.x,iResolution.y/cells.y);
return mix(.5,hash21(cell+vec2(fr*17.,fr*29.)),detailFade(2.*grainPx));
}
float dcHum(float y,float t,float amt){
float b=fract(y*.5-t*.12);
return 1.-amt*.09*smoothstep(0.,.25,b)*smoothstep(.6,.25,b);
}
float dcFlicker(float t,float amt){
return 1.-amt*.045*hash11(floor(t*24.)+.5);
}
float dcGhost(vec2 p,float px,float t){
vec2 w=vec2(fbmPx(p*3.+vec2(0.,t*.4),px*3.),fbmPx(p*3.+vec2(9.1,-t*.3),px*3.));
vec2 q=p+.05*w;
float head=length(q/vec2(.46,.6))-1.;
float eyes=min(length((vec2(abs(q.x),q.y)-vec2(.17,.1))/vec2(.1,.06)),
length((q-vec2(0.,-.3))/vec2(.15,.045)))-1.;
float face=smoothstep(.2,-.45,head)*(.75+.25*w.x);
return face*smoothstep(-.6,.35,eyes);
}
vec2 dcPower(vec2 q,float k,out float gain,out float flatten){
flatten=1.-smoothstep(.86,.98,k);
float sy=max(clamp(k*2.-1.,0.,1.),.006);
float sx=max(clamp(k*2.,0.,1.),.003);
vec2 c=(q-.5)/vec2(sx,sy);
float on=smoothstep(0.,.06,k)*step(abs(c.x),.5)*step(abs(c.y),.5);
gain=on*(1.+.9*(1.-sy));
return c+.5;
}
vec3 finalize(vec3 col,vec2 uv){
#ifdef PROFILE_RETRO
return retroFinalize(col,uv,gl_FragCoord.xy,PALETTE,PALETTE_N);
#else
float d=hash21(floor(uv*iResolution.xy))-.5;
return clamp(col+d/255.,0.,1.);
#endif
}

scenes.card:
float dcBlip(float t,float c,float w){
return smoothstep(w,0.,abs(t-c));
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 uv=fragCoord/iResolution.xy;
float ax=iResolution.x/iResolution.y;
float px=2./iResolution.y;
float inside;
vec2 q=dcScreen(uv,px,inside);
vec2 p=(q-.5)*vec2(ax,1.)*2.;
float t=uSceneTime;
float unrest=smoothstep(.5,1.,uSceneProgress);
p.x+=dcTear(p.y,t,unrest*.3);
float mis=.002+.004*abs(p.x)/ax;
float clock=DC_CLOCK0+iTime;
vec4 glyph;
vec3 ink;
vec4 g2;
vec3 i2;
vec3 col=dcCard(p,ax,px,clock,0,0.,glyph,ink);
col.r=dcCard(p+vec2(mis,0.),ax,px,clock,0,0.,g2,i2).r;
col=mix(col,ink,dcGlyph(p,glyph));
float seen=dcBlip(t,15.2,.45)+.8*dcBlip(t,19.6,.35);
if(seen>0.){
float g=dcGhost(p,px,t);
col=mix(col,vec3(.8,.88,.95),g*seen*.35);
}
col*=dcHum(q.y,t,unrest);
col=dcTube(col,q,inside);
fragColor=vec4(finalize(col,uv),1.);
}

