local=vec3(fx,id,top);
float side=min(fx-.06,.94-fx)*w;
return dcFill(p.y-top,px)*dcFill(-side,px);
}
vec3 dcWindows(vec2 p,vec3 local,float rows,float t){
vec2 cell=vec2(floor(local.x*6.),floor(p.y*rows));
vec2 f=vec2(fract(local.x*6.),fract(p.y*rows));
float h=hash21(cell+vec2(local.y*13.,3.));
